# -*- coding: utf-8 -*-
"""포켓몬 도구 그림 아이콘 (DP 테마의 탭 · 머리 그림).

아이콘을 직접 그리지 않는다 (사용자 지시) - 본가 4세대 도구 그림을 쓴다. 출처는 게임의 도구 그림과 같은
PokeAPI sprites (https://github.com/PokeAPI/sprites, sprites/items/<이름>.png). 그림의 권리는
Nintendo · Creatures · GAME FREAK 에 있다. 둘레의 빈칸은 잘라 냈다 (가로세로 18~22px).

도트라서 늘리면 정수 배로만 늘린다 (scale). 줄이지 않는다 - 흐려진다.

    photo("town-map")          그대로 (tk 이미지, 만든 것은 들고 있는다)
    photo("poke-ball", 2)      두 배
    NAMES                       들어 있는 이름
"""
import base64
import io

PNG = {
    "poke-ball": "",
    "loot-sack": "",
    "explorer-kit": "",
    "coin-case": "",
    "amulet-coin": "",
    "town-map": "",
    "pal-pad": "",
    "xtransceiver": "",
    "member-card": "",
    "point-card": "",
    "journal": "",
    "rule-book": "",
    "seal-case": "",
    "fashion-case": "",
    "vs-seeker": "",
    "poke-radar": "",
    "dowsing-machine": "",
}
NAMES = tuple(PNG)
_cache = {}


def photo(name, scale=1):
    """그 도구 그림의 tk 이미지. 없는 이름이면 None. tk 스레드에서 부를 것."""
    key = (name, int(scale))
    if key in _cache:
        return _cache[key]
    data = PNG.get(name)
    if data is None:
        return None
    from PIL import Image, ImageTk
    im = Image.open(io.BytesIO(base64.b64decode(data))).convert("RGBA")
    if key[1] > 1:
        im = im.resize((im.width * key[1], im.height * key[1]), Image.NEAREST)
    ph = ImageTk.PhotoImage(im)
    _cache[key] = ph
    return ph
